-- Aprenda se Divertindo · 89 · Simulado 1 do Enem
-- Rode depois do 88-simulado-policial-1.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o primeiro Simulado de Domingo da trilha Enem: domingo, 25/10/2026, das 0h às 23h59.
-- 80 questões de A a E no estilo Enem (20 por área: Linguagens, Humanas, Natureza e Matemática), 5 horas de prova.
-- Gabarito comentado liberado na segunda, às 0h. Rodar de novo atualiza as questões, desde que ninguém tenha começado a prova.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "ling", "texto_base": "Durante muito tempo, a escola tratou o celular como inimigo. Proibia-se o aparelho na sala de aula, e quem fosse flagrado com ele tinha o objeto recolhido até o fim do dia. Hoje, o debate é mais complexo. Pesquisas mostram que o uso livre das telas durante a aula prejudica a atenção e a memória, mas também há professores que usam o celular para pesquisas, gravação de vídeos e aplicativos de leitura.\n\nO problema, portanto, talvez não seja o aparelho em si, e sim a ausência de regras claras. Uma ferramenta pode servir para aprender ou para distrair; o que define seu papel é a intenção de quem a usa e o contexto em que ela aparece.", "enunciado": "O texto tem como principal objetivo", "opcoes": ["comprovar que a leitura em telas é sempre melhor do que a leitura no papel.", "defender que o uso do celular na escola depende de regras e finalidade, e não apenas do aparelho.", "informar que o celular foi definitivamente proibido nas escolas brasileiras.", "narrar a história de um aluno flagrado usando o celular em sala.", "convencer os pais a recolherem o celular dos filhos durante a noite."], "gabarito": 1, "explicacao": "O texto apresenta os dois lados e conclui que o problema 'talvez não seja o aparelho em si, e sim a ausência de regras claras'. É um texto de caráter argumentativo."}, {"materia": "ling", "texto_base": "Durante muito tempo, a escola tratou o celular como inimigo. Proibia-se o aparelho na sala de aula, e quem fosse flagrado com ele tinha o objeto recolhido até o fim do dia. Hoje, o debate é mais complexo. Pesquisas mostram que o uso livre das telas durante a aula prejudica a atenção e a memória, mas também há professores que usam o celular para pesquisas, gravação de vídeos e aplicativos de leitura.\n\nO problema, portanto, talvez não seja o aparelho em si, e sim a ausência de regras claras. Uma ferramenta pode servir para aprender ou para distrair; o que define seu papel é a intenção de quem a usa e o contexto em que ela aparece.", "enunciado": "No trecho \"O problema, portanto, talvez não seja o aparelho em si\", a palavra \"portanto\" introduz uma", "opcoes": ["oposição ao que foi dito no parágrafo anterior.", "explicação da causa de um fato.", "comparação entre dois elementos.", "conclusão a partir do que foi exposto antes.", "condição para que algo aconteça."], "gabarito": 3, "explicacao": "\"Portanto\" é conjunção conclusiva: o autor tira uma conclusão dos argumentos apresentados no primeiro parágrafo."}, {"materia": "ling", "texto_base": "Durante muito tempo, a escola tratou o celular como inimigo. Proibia-se o aparelho na sala de aula, e quem fosse flagrado com ele tinha o objeto recolhido até o fim do dia. Hoje, o debate é mais complexo. Pesquisas mostram que o uso livre das telas durante a aula prejudica a atenção e a memória, mas também há professores que usam o celular para pesquisas, gravação de vídeos e aplicativos de leitura.\n\nO problema, portanto, talvez não seja o aparelho em si, e sim a ausência de regras claras. Uma ferramenta pode servir para aprender ou para distrair; o que define seu papel é a intenção de quem a usa e o contexto em que ela aparece.", "enunciado": "No texto, a expressão \"Uma ferramenta pode servir para aprender ou para distrair\" reforça a ideia de que", "opcoes": ["o efeito do celular depende do uso que se faz dele.", "o celular só serve para distrair os alunos.", "as pesquisas sobre o tema são todas contraditórias.", "os professores não sabem usar a tecnologia.", "a escola deve abolir qualquer tecnologia."], "gabarito": 0, "explicacao": "A frase mostra que a mesma ferramenta pode ter usos opostos, e o texto completa: 'o que define seu papel é a intenção de quem a usa e o contexto'."}, {"materia": "ling", "texto_base": "Minha terra tem palmeiras,\nOnde canta o Sabiá;\nAs aves, que aqui gorjeiam,\nNão gorjeiam como lá.\n\n(Gonçalves Dias, Canção do Exílio, 1843)", "enunciado": "No poema de Gonçalves Dias, os advérbios \"aqui\" e \"lá\" contrapõem, respectivamente,", "opcoes": ["a cidade e o campo brasileiros.", "a terra estrangeira, onde está o eu lírico, e a terra natal, de que ele sente saudade.", "o céu e a terra.", "a terra natal e uma terra que o eu lírico deseja conhecer.", "o passado e o futuro do país."], "gabarito": 1, "explicacao": "O poema foi escrito no exílio, em Portugal. \"Aqui\" é onde o eu lírico está (o estrangeiro) e \"lá\" é a pátria idealizada."}, {"materia": "ling", "texto_base": "Minha terra tem palmeiras,\nOnde canta o Sabiá;\nAs aves, que aqui gorjeiam,\nNão gorjeiam como lá.\n\n(Gonçalves Dias, Canção do Exílio, 1843)", "enunciado": "A exaltação da natureza e da pátria, presente na Canção do Exílio, é característica marcante do", "opcoes": ["Barroco.", "Realismo.", "Romantismo, em sua primeira geração (nacionalista ou indianista).", "Modernismo de 1922.", "Arcadismo."], "gabarito": 2, "explicacao": "A primeira geração romântica brasileira valorizou a natureza, a pátria e o indígena como símbolos da identidade nacional, logo após a Independência."}, {"materia": "ling", "texto_base": null, "enunciado": "A Semana de Arte Moderna de 1922, realizada em São Paulo, é considerada um marco do Modernismo brasileiro por", "opcoes": ["proibir o uso da língua falada na literatura.", "propor a ruptura com modelos tradicionais e a valorização de uma linguagem artística mais livre e ligada à realidade brasileira.", "defender o retorno às formas fixas e à linguagem rebuscada do Parnasianismo.", "reunir apenas escritores portugueses.", "inaugurar o Romantismo no Brasil."], "gabarito": 1, "explicacao": "Os modernistas criticaram o academicismo, defenderam o verso livre, a linguagem coloquial e a busca de uma arte com identidade brasileira."}, {"materia": "ling", "texto_base": "Cartaz de campanha\n\nDOE SANGUE.\nLeva menos de uma hora.\nPode salvar até quatro vidas.\nProcure o hemocentro mais perto de você.", "enunciado": "No cartaz, predomina a função da linguagem", "opcoes": ["poética, pois o foco está na forma da mensagem.", "apelativa (conativa), pois busca convencer o leitor a agir.", "metalinguística, pois o código explica o próprio código.", "fática, pois testa o canal de comunicação.", "emotiva, pois expressa os sentimentos do emissor."], "gabarito": 1, "explicacao": "O verbo no imperativo (\"Doe\", \"Procure\") e o foco no receptor caracterizam a função conativa, típica da publicidade e das campanhas."}, {"materia": "ling", "texto_base": "— Ô, véio, cê vai no jogo amanhã?\n— Vô sim, mas só se num chovê. Se chovê, fico em casa assistindo na TV mesmo.", "enunciado": "O diálogo reproduz marcas da linguagem", "opcoes": ["oral e informal, que são adequadas à situação de conversa entre amigos.", "arcaica, que não é mais usada no Brasil.", "errada, que deve ser sempre corrigida em qualquer situação.", "formal, própria de documentos oficiais.", "técnica, própria de manuais científicos."], "gabarito": 0, "explicacao": "Formas como \"cê\", \"vô\", \"num\" e \"chovê\" são marcas da fala informal. O Enem trata a variação linguística como adequação à situação, sem preconceito linguístico."}, {"materia": "ling", "texto_base": "— Ô, véio, cê vai no jogo amanhã?\n— Vô sim, mas só se num chovê. Se chovê, fico em casa assistindo na TV mesmo.", "enunciado": "O respeito às diferentes formas de falar, como as do diálogo, está relacionado ao combate ao", "opcoes": ["regionalismo literário.", "ensino da norma-padrão.", "preconceito linguístico.", "estrangeirismo.", "uso de gírias na internet."], "gabarito": 2, "explicacao": "Preconceito linguístico é a discriminação de pessoas pelo modo como falam. Variedades populares e regionais são legítimas, cada uma adequada a certos contextos."}, {"materia": "ling", "texto_base": null, "enunciado": "Na frase \"Aquele jogador é uma muralha no gol\", ocorre a figura de linguagem chamada", "opcoes": ["hipérbole.", "onomatopeia.", "ironia.", "eufemismo.", "metáfora."], "gabarito": 4, "explicacao": "Há uma comparação implícita, sem conectivo: o jogador é visto como uma muralha. Com \"como\", seria uma comparação (símile)."}, {"materia": "ling", "texto_base": null, "enunciado": "Em \"Já te disse um milhão de vezes para arrumar o quarto\", a figura de linguagem é a", "opcoes": ["metáfora.", "hipérbole.", "prosopopeia.", "antítese.", "metonímia."], "gabarito": 1, "explicacao": "Hipérbole é o exagero intencional para dar ênfase."}, {"materia": "ling", "texto_base": null, "enunciado": "Uma notícia publicada em um portal de jornalismo tem, como característica principal,", "opcoes": ["relatar um fato recente de interesse público, de forma objetiva, respondendo a perguntas como o quê, quem, quando e onde.", "narrar uma história fictícia com personagens inventados.", "defender abertamente a opinião do autor sobre o tema.", "ensinar o passo a passo de uma receita.", "convencer o leitor a comprar um produto."], "gabarito": 0, "explicacao": "A notícia é um gênero informativo. A defesa de opinião é típica do artigo de opinião e do editorial."}, {"materia": "ling", "texto_base": null, "enunciado": "Ao usar o pronome \"você\" para se dirigir ao leitor, em vez de \"o cidadão\", um texto de campanha pública busca, principalmente,", "opcoes": ["tornar o texto mais formal e distante.", "evitar que o leitor entenda a mensagem.", "falar de um terceiro ausente da conversa.", "mostrar desconhecimento da norma-padrão.", "aproximar-se do leitor e criar envolvimento com a mensagem."], "gabarito": 4, "explicacao": "O tratamento direto em segunda pessoa (\"você\") cria proximidade, recurso comum em textos que querem convencer."}, {"materia": "ling", "texto_base": "Reading is not only a school activity. A recent survey showed that young people who read for pleasure at least thirty minutes a day tend to have a richer vocabulary and better writing skills. Researchers also found that it does not matter much whether the reading is on paper or on a screen: what makes the difference is the habit.", "enunciado": "According to the text, what really makes a difference for young readers is", "opcoes": ["reading for exactly thirty minutes.", "reading only on paper.", "the habit of reading.", "reading only on screens.", "reading at school."], "gabarito": 2, "explicacao": "\"What makes the difference is the habit\": o texto diz que o suporte (papel ou tela) importa pouco."}, {"materia": "ling", "texto_base": "Reading is not only a school activity. A recent survey showed that young people who read for pleasure at least thirty minutes a day tend to have a richer vocabulary and better writing skills. Researchers also found that it does not matter much whether the reading is on paper or on a screen: what makes the difference is the habit.", "enunciado": "No texto, a expressão \"for pleasure\" indica que a leitura é feita", "opcoes": ["por prazer.", "para uma prova.", "por obrigação.", "em voz alta.", "em grupo."], "gabarito": 0, "explicacao": "\"For pleasure\" significa \"por prazer\", ou seja, por vontade própria."}, {"materia": "ling", "texto_base": "WARNING\nWet floor.\nPlease use the handrail.", "enunciado": "The sign tells people that", "opcoes": ["the place is closed.", "the floor is dry and safe.", "the floor is wet and they should hold the handrail.", "they should clean the floor.", "they must not use the stairs."], "gabarito": 2, "explicacao": "\"Wet floor\" significa piso molhado, e \"use the handrail\" significa \"use o corrimão\"."}, {"materia": "ling", "texto_base": "Na capoeira, o jogo acontece dentro da roda, ao som do berimbau, do pandeiro e das palmas. Os movimentos de ataque e defesa se alternam sem que, em geral, haja contato forte entre os jogadores. Reconhecida como patrimônio cultural imaterial, a capoeira reúne luta, dança, música e história, e guarda a memória da resistência dos africanos escravizados no Brasil.", "enunciado": "De acordo com o texto, a capoeira é uma prática corporal que", "opcoes": ["proíbe o uso de instrumentos musicais.", "tem como objetivo principal derrubar o adversário com golpes fortes.", "é apenas um esporte de competição olímpica.", "reúne luta, dança, música e história, e é reconhecida como patrimônio cultural.", "surgiu recentemente, sem relação com a história do Brasil."], "gabarito": 3, "explicacao": "O texto destaca o caráter múltiplo da capoeira e sua ligação com a memória da resistência dos africanos escravizados."}, {"materia": "ling", "texto_base": null, "enunciado": "A prática regular de atividade física, segundo as recomendações de saúde, traz benefícios como", "opcoes": ["garantia de emagrecimento rápido sem mudança na alimentação.", "eliminação da necessidade de descanso.", "aumento do risco de doenças do coração em qualquer pessoa.", "substituição de qualquer tratamento médico.", "melhora do condicionamento cardiorrespiratório e redução do risco de doenças crônicas."], "gabarito": 4, "explicacao": "A atividade física regular melhora a capacidade cardiorrespiratória e reduz o risco de hipertensão, diabetes tipo 2 e outras doenças crônicas."}, {"materia": "ling", "texto_base": null, "enunciado": "Um meme que combina uma imagem conhecida com uma frase sobre um fato do dia é um exemplo de texto", "opcoes": ["exclusivamente verbal.", "multimodal, que une linguagem verbal e não verbal para produzir sentido.", "jurídico, com valor de lei.", "literário em versos rimados.", "científico, com linguagem técnica."], "gabarito": 1, "explicacao": "Textos multimodais combinam palavras, imagens, cores e outros recursos. O sentido do meme depende da relação entre a imagem e a frase."}, {"materia": "ling", "texto_base": null, "enunciado": "Na frase \"Ela não é feia; é apenas diferente do padrão\", a palavra \"apenas\" tem o efeito de", "opcoes": ["intensificar a crítica.", "indicar lugar.", "expressar dúvida absoluta.", "indicar tempo passado.", "atenuar a afirmação, limitando seu alcance."], "gabarito": 4, "explicacao": "\"Apenas\" restringe e suaviza o que se diz, funcionando como palavra de sentido restritivo."}, {"materia": "his", "texto_base": "Art. 1º É declarada extinta desde a data desta lei a escravidão no Brasil.\nArt. 2º Revogam-se as disposições em contrário.\n\n(Lei nº 3.353, de 13 de maio de 1888)", "enunciado": "A lei transcrita, conhecida como Lei Áurea, foi assinada no Brasil durante o", "opcoes": ["Segundo Reinado, pela princesa Isabel.", "Primeiro Reinado, por D. Pedro I.", "período regencial, pelo regente Feijó.", "governo provisório de Deodoro da Fonseca.", "governo de Getúlio Vargas."], "gabarito": 0, "explicacao": "A Lei Áurea é de 13 de maio de 1888 e foi assinada pela princesa Isabel, regente do Império, no Segundo Reinado de D. Pedro II."}, {"materia": "his", "texto_base": "Art. 1º É declarada extinta desde a data desta lei a escravidão no Brasil.\nArt. 2º Revogam-se as disposições em contrário.\n\n(Lei nº 3.353, de 13 de maio de 1888)", "enunciado": "Um problema histórico relacionado ao modo como a abolição foi feita no Brasil é que", "opcoes": ["a escravidão continuou legal por mais cinquenta anos.", "não houve políticas de integração dos libertos, como acesso a terra, educação e trabalho digno.", "a lei foi aprovada por plebiscito popular.", "os escravizados receberam grandes indenizações do governo.", "todos os libertos foram enviados de volta à África."], "gabarito": 1, "explicacao": "A lei tem apenas dois artigos e não previu nenhuma medida de inclusão, o que contribuiu para a marginalização da população negra."}, {"materia": "his", "texto_base": null, "enunciado": "A Revolução Francesa, iniciada em 1789, ficou associada ao lema", "opcoes": ["\"Liberdade, Igualdade, Fraternidade\".", "\"Deus, Pátria e Família\".", "\"Paz, Terra e Pão\".", "\"Independência ou Morte\".", "\"Ordem e Progresso\"."], "gabarito": 0, "explicacao": "O lema sintetiza os ideais iluministas da Revolução. \"Paz, Terra e Pão\" foi o lema bolchevique de 1917, e \"Ordem e Progresso\" está na bandeira do Brasil, de inspiração positivista."}, {"materia": "his", "texto_base": null, "enunciado": "A Revolução Industrial, iniciada na Inglaterra no século XVIII, teve como uma de suas consequências", "opcoes": ["a volta ao sistema feudal.", "a diminuição da população urbana.", "o fim do trabalho assalariado.", "a mecanização da produção e o crescimento das cidades industriais, com longas jornadas de trabalho nas fábricas.", "o desaparecimento das máquinas a vapor."], "gabarito": 3, "explicacao": "A máquina a vapor e a produção fabril transformaram o trabalho, atraíram trabalhadores para as cidades e geraram condições duras, o que levou ao surgimento dos movimentos operários."}, {"materia": "his", "texto_base": null, "enunciado": "O período de 1964 a 1985 no Brasil foi marcado por", "opcoes": ["um regime militar, com censura, restrição de direitos políticos e atos institucionais.", "eleições diretas para presidente a cada quatro anos.", "a abolição da escravidão.", "uma monarquia parlamentarista.", "a primeira Constituição republicana."], "gabarito": 0, "explicacao": "Os governos militares editaram atos institucionais, como o AI-5 (1968), censuraram a imprensa e perseguiram opositores. A redemocratização culminou na Constituição de 1988."}, {"materia": "his", "texto_base": null, "enunciado": "A Constituição de 1988 é chamada de \"Constituição Cidadã\" principalmente por", "opcoes": ["extinguir os direitos trabalhistas.", "ter sido outorgada pelo presidente sem participação do Congresso.", "proibir o voto dos analfabetos.", "ampliar direitos e garantias fundamentais e sociais após o fim do regime militar.", "restabelecer a monarquia."], "gabarito": 3, "explicacao": "Elaborada por uma Assembleia Constituinte, ela ampliou direitos civis, políticos e sociais, como o SUS e o voto facultativo dos analfabetos."}, {"materia": "his", "texto_base": null, "enunciado": "A Guerra Fria (1947–1991) caracterizou-se pela", "opcoes": ["guerra declarada e direta entre Alemanha e França.", "aliança permanente entre capitalistas e socialistas.", "disputa política, econômica e ideológica entre Estados Unidos e União Soviética, sem confronto militar direto entre eles.", "unificação de todos os países da Europa sob um só governo.", "expansão do Império Romano."], "gabarito": 2, "explicacao": "Foi um conflito indireto, com corrida armamentista e espacial e guerras em outros países, como Coreia e Vietnã. Terminou com o fim da URSS, em 1991."}, {"materia": "geo", "texto_base": "Entre 1950 e 2020, a população urbana do Brasil passou de cerca de um terço para mais de quatro quintos do total. Em poucas décadas, milhões de pessoas deixaram o campo em direção às cidades, especialmente às capitais do Sudeste.", "enunciado": "O processo descrito no texto é chamado de", "opcoes": ["ruralização da população.", "migração pendular.", "transumância.", "êxodo rural, que acelerou a urbanização brasileira.", "diáspora internacional."], "gabarito": 3, "explicacao": "Êxodo rural é a saída em massa do campo para as cidades. No Brasil, ele foi intenso a partir da industrialização e da mecanização do campo."}, {"materia": "geo", "texto_base": "Entre 1950 e 2020, a população urbana do Brasil passou de cerca de um terço para mais de quatro quintos do total. Em poucas décadas, milhões de pessoas deixaram o campo em direção às cidades, especialmente às capitais do Sudeste.", "enunciado": "Uma consequência da urbanização rápida e pouco planejada nas grandes cidades brasileiras foi", "opcoes": ["a eliminação das desigualdades sociais.", "o fim do trânsito nas capitais.", "a diminuição da população das metrópoles.", "o abandono completo da agricultura no país.", "o crescimento de moradias precárias e a falta de infraestrutura em áreas periféricas."], "gabarito": 4, "explicacao": "Sem planejamento e moradia acessível, muitas famílias ocuparam áreas sem saneamento, transporte e serviços públicos adequados."}, {"materia": "geo", "texto_base": null, "enunciado": "O bioma brasileiro conhecido como \"berço das águas\", por abrigar nascentes de importantes bacias hidrográficas e ser marcado por árvores de troncos retorcidos e estação seca bem definida, é o", "opcoes": ["Pampa.", "Mata Atlântica.", "Manguezal.", "Pantanal.", "Cerrado."], "gabarito": 4, "explicacao": "O Cerrado, no Planalto Central, abriga nascentes de bacias como a do São Francisco, do Tocantins-Araguaia e do Paraná."}, {"materia": "geo", "texto_base": null, "enunciado": "O aquecimento global está associado principalmente ao aumento, na atmosfera, da concentração de", "opcoes": ["gases de efeito estufa, como o dióxido de carbono e o metano.", "ozônio na estratosfera.", "gás hélio.", "oxigênio.", "nitrogênio."], "gabarito": 0, "explicacao": "A queima de combustíveis fósseis e o desmatamento elevam a concentração de CO₂ e de outros gases que intensificam o efeito estufa."}, {"materia": "geo", "texto_base": null, "enunciado": "A escala de um mapa é 1:100.000. Uma distância de 5 cm no mapa corresponde, na realidade, a", "opcoes": ["500 m.", "50 m.", "5 km.", "500 km.", "50 km."], "gabarito": 2, "explicacao": "5 cm × 100.000 = 500.000 cm = 5.000 m = 5 km."}, {"materia": "geo", "texto_base": null, "enunciado": "A globalização intensificou-se a partir do final do século XX com", "opcoes": ["a proibição da internet.", "o avanço das tecnologias de comunicação e transporte e a maior circulação de mercadorias, capitais e informações.", "o fim do comércio internacional.", "o isolamento econômico dos países.", "a volta do trabalho escravo como regra mundial."], "gabarito": 1, "explicacao": "Internet, contêineres e transporte aéreo reduziram distâncias e aceleraram os fluxos de bens, dinheiro e informação."}, {"materia": "geo", "texto_base": null, "enunciado": "A inversão térmica, comum no inverno em grandes cidades, agrava a poluição do ar porque", "opcoes": ["a chuva aumenta e limpa a atmosfera.", "os ventos ficam mais fortes.", "a camada de ozônio desaparece.", "uma camada de ar quente fica acima do ar frio junto ao solo, dificultando a dispersão dos poluentes.", "o ar quente sobe com mais facilidade e leva os poluentes embora."], "gabarito": 3, "explicacao": "Normalmente o ar próximo ao solo é mais quente e sobe. Na inversão, o ar frio fica preso embaixo, e os poluentes se acumulam."}, {"materia": "fil", "texto_base": null, "enunciado": "Para Sócrates, a frase \"Só sei que nada sei\" expressa", "opcoes": ["a impossibilidade total de conhecer qualquer coisa.", "a consciência da própria ignorância como ponto de partida para buscar o conhecimento.", "o desprezo pela filosofia.", "a certeza de que tudo já é conhecido.", "a defesa de que o saber vem só dos sentidos."], "gabarito": 1, "explicacao": "A ironia socrática começa reconhecendo a ignorância. A partir daí, pelo diálogo (maiêutica), busca-se o conhecimento verdadeiro."}, {"materia": "fil", "texto_base": null, "enunciado": "Na alegoria da caverna, Platão representa", "opcoes": ["a passagem do mundo das aparências (sombras) para o conhecimento verdadeiro (mundo das ideias).", "um mito sobre a criação do mundo.", "a defesa da escravidão.", "a vida dos homens primitivos.", "a superioridade dos sentidos sobre a razão."], "gabarito": 0, "explicacao": "Os prisioneiros veem apenas sombras. Quem sai da caverna e vê a luz do sol simboliza o filósofo que alcança as ideias verdadeiras."}, {"materia": "fil", "texto_base": null, "enunciado": "Para o Iluminismo, o principal instrumento para o progresso humano e a crítica ao absolutismo era", "opcoes": ["a superstição.", "a força militar.", "a vontade do rei.", "a razão.", "a tradição religiosa."], "gabarito": 3, "explicacao": "Pensadores como Locke, Montesquieu, Voltaire e Rousseau defenderam a razão, a liberdade e a limitação do poder dos governantes."}, {"materia": "fil", "texto_base": null, "enunciado": "Montesquieu defendeu a separação dos poderes do Estado em", "opcoes": ["Imprensa, escola e família.", "Monarquia, Igreja e Nobreza.", "Polícia, Exército e Marinha.", "Legislativo, Executivo e Judiciário.", "União, estados e municípios."], "gabarito": 3, "explicacao": "Em \"O Espírito das Leis\" (1748), Montesquieu propôs a divisão dos poderes para evitar abusos."}, {"materia": "fil", "texto_base": null, "enunciado": "Para o sociólogo Émile Durkheim, fato social é", "opcoes": ["uma escolha totalmente livre de cada pessoa.", "um conflito entre classes sociais.", "uma maneira de agir, pensar e sentir exterior ao indivíduo, geral e dotada de poder de coerção.", "um fenômeno exclusivamente biológico.", "uma ação individual sem relação com a sociedade."], "gabarito": 2, "explicacao": "As características do fato social para Durkheim são exterioridade, generalidade e coercitividade. O conflito de classes é central em Marx."}, {"materia": "fil", "texto_base": null, "enunciado": "Para Karl Marx, a sociedade capitalista é marcada pelo conflito entre", "opcoes": ["o campo e a cidade, sem relação com o trabalho.", "os senhores feudais e os servos, apenas.", "a burguesia, dona dos meios de produção, e o proletariado, que vende sua força de trabalho.", "os cidadãos e os estrangeiros.", "o clero e a nobreza."], "gabarito": 2, "explicacao": "Marx analisa a luta de classes e a exploração do trabalho assalariado, com conceitos como mais-valia."}, {"materia": "bio", "texto_base": "A dengue é uma doença viral transmitida pela picada da fêmea do mosquito Aedes aegypti. O mosquito deposita seus ovos em recipientes com água parada, como pneus, vasos de plantas e caixas-d'água destampadas. Os ovos podem resistir por meses em locais secos e eclodir quando entram em contato com a água.", "enunciado": "Considerando o texto, a medida mais eficaz para reduzir os casos de dengue em uma comunidade é", "opcoes": ["usar máscara em locais fechados.", "tomar antibióticos de forma preventiva.", "ferver toda a água antes de beber.", "evitar o contato com pessoas doentes, pois a doença passa pelo ar.", "eliminar recipientes com água parada e manter caixas-d'água tampadas."], "gabarito": 4, "explicacao": "A dengue não é transmitida de pessoa para pessoa nem pela água de beber. Combater os criadouros interrompe o ciclo do mosquito. Antibióticos não agem contra vírus."}, {"materia": "bio", "texto_base": "A dengue é uma doença viral transmitida pela picada da fêmea do mosquito Aedes aegypti. O mosquito deposita seus ovos em recipientes com água parada, como pneus, vasos de plantas e caixas-d'água destampadas. Os ovos podem resistir por meses em locais secos e eclodir quando entram em contato com a água.", "enunciado": "O fato de os ovos resistirem por meses em locais secos indica que", "opcoes": ["é preciso limpar e escovar os recipientes, e não apenas esvaziá-los.", "o mosquito só se reproduz no inverno.", "os ovos morrem rapidamente sem água.", "basta esvaziar os recipientes uma vez por ano.", "os ovos só eclodem em água salgada."], "gabarito": 0, "explicacao": "Como os ovos ficam aderidos às paredes dos recipientes e resistem à seca, a limpeza com escovação é recomendada."}, {"materia": "bio", "texto_base": null, "enunciado": "Na fotossíntese, as plantas utilizam a energia luminosa para produzir", "opcoes": ["água a partir de sais minerais.", "glicose e oxigênio, a partir de gás carbônico e água.", "gás carbônico e água, a partir de glicose e oxigênio.", "oxigênio a partir de nitrogênio.", "proteínas a partir de luz apenas."], "gabarito": 1, "explicacao": "6 CO₂ + 6 H₂O + luz → C₆H₁₂O₆ + 6 O₂. O processo inverso, que libera energia, é a respiração celular."}, {"materia": "bio", "texto_base": null, "enunciado": "Em um casal em que os dois são heterozigotos (Aa) para uma característica recessiva, a probabilidade de um filho ser homozigoto recessivo (aa) é de", "opcoes": ["75%.", "0%.", "25%.", "50%.", "100%."], "gabarito": 2, "explicacao": "Aa × Aa gera AA, Aa, Aa e aa: 1 em 4, ou seja, 25%."}, {"materia": "bio", "texto_base": null, "enunciado": "Em uma cadeia alimentar, a quantidade de energia disponível", "opcoes": ["é maior nos consumidores do topo da cadeia.", "aumenta a cada nível trófico.", "permanece igual em todos os níveis.", "diminui a cada nível trófico, pois parte dela é perdida como calor nas atividades dos seres vivos.", "é criada pelos decompositores."], "gabarito": 3, "explicacao": "O fluxo de energia é unidirecional e decrescente. Por isso, as cadeias costumam ter poucos níveis."}, {"materia": "bio", "texto_base": null, "enunciado": "As vacinas protegem o organismo porque", "opcoes": ["substituem o sistema imunológico.", "matam qualquer bactéria presente no corpo.", "funcionam como antibióticos.", "contêm anticorpos prontos que duram para sempre.", "estimulam o sistema imunológico a produzir anticorpos e células de memória contra o agente."], "gabarito": 4, "explicacao": "A vacina gera imunização ativa: o corpo aprende a reconhecer o antígeno. O soro, ao contrário, já traz anticorpos prontos (imunização passiva)."}, {"materia": "bio", "texto_base": null, "enunciado": "Segundo a teoria da seleção natural de Darwin,", "opcoes": ["os seres vivos não mudam ao longo do tempo.", "o ambiente provoca mutações sempre úteis.", "todas as espécies surgiram ao mesmo tempo.", "as características adquiridas pelo uso são transmitidas aos filhos.", "indivíduos com características mais vantajosas para o ambiente tendem a sobreviver e deixar mais descendentes."], "gabarito": 4, "explicacao": "A transmissão de características adquiridas pelo uso e desuso é a teoria de Lamarck. Darwin propôs que o ambiente seleciona as variações já existentes."}, {"materia": "qui", "texto_base": null, "enunciado": "Uma solução com pH igual a 3 é classificada como", "opcoes": ["ácida.", "neutra.", "salina neutra.", "básica.", "alcalina forte."], "gabarito": 0, "explicacao": "Na escala de pH a 25 °C, valores menores que 7 são ácidos, 7 é neutro e acima de 7 é básico."}, {"materia": "qui", "texto_base": null, "enunciado": "Para obter água pura a partir de água do mar, o processo de separação mais adequado é a", "opcoes": ["filtração.", "decantação.", "peneiração.", "destilação.", "imantação."], "gabarito": 3, "explicacao": "O sal está dissolvido na água (mistura homogênea). A destilação separa a água por evaporação e condensação. A filtração só separa sólidos não dissolvidos."}, {"materia": "qui", "texto_base": null, "enunciado": "Foram dissolvidos 20 g de sal em água até completar 500 mL de solução. A concentração dessa solução é de", "opcoes": ["25 g/L.", "0,04 g/L.", "10 g/L.", "100 g/L.", "40 g/L."], "gabarito": 4, "explicacao": "500 mL = 0,5 L. C = 20 g ÷ 0,5 L = 40 g/L."}, {"materia": "qui", "texto_base": null, "enunciado": "Sabendo que a massa molar da água é 18 g/mol, a quantidade de matéria em 36 g de água é", "opcoes": ["0,5 mol.", "2 mol.", "18 mol.", "36 mol.", "1 mol."], "gabarito": 1, "explicacao": "n = 36 ÷ 18 = 2 mol."}, {"materia": "qui", "texto_base": null, "enunciado": "A chuva ácida é causada principalmente pela emissão de", "opcoes": ["gás hélio pelos balões.", "óxidos de enxofre e de nitrogênio, liberados na queima de combustíveis fósseis.", "oxigênio pelas plantas.", "nitrogênio puro pelo solo.", "vapor de água pelos oceanos."], "gabarito": 1, "explicacao": "SO₂ e NOₓ reagem com a água da atmosfera formando ácidos, como o sulfúrico e o nítrico."}, {"materia": "qui", "texto_base": null, "enunciado": "Na combustão completa do etanol, usado como combustível em carros, são produzidos", "opcoes": ["nitrogênio e oxigênio.", "monóxido de carbono apenas.", "gás carbônico e água.", "oxigênio e hidrogênio.", "metano e água."], "gabarito": 2, "explicacao": "C₂H₅OH + 3 O₂ → 2 CO₂ + 3 H₂O. Na combustão incompleta também se forma CO."}, {"materia": "qui", "texto_base": null, "enunciado": "É exemplo de transformação química:", "opcoes": ["o derretimento do gelo.", "a quebra de um copo de vidro.", "a dissolução do açúcar no café.", "a evaporação da água.", "a queima de uma folha de papel."], "gabarito": 4, "explicacao": "Na queima formam-se novas substâncias (CO₂, H₂O e cinzas). As demais são transformações físicas, sem mudança na composição das substâncias."}, {"materia": "fis", "texto_base": null, "enunciado": "Um ônibus percorre 120 km em 1 hora e 30 minutos. Sua velocidade média é de", "opcoes": ["120 km/h.", "180 km/h.", "80 km/h.", "60 km/h.", "90 km/h."], "gabarito": 2, "explicacao": "1 h 30 min = 1,5 h. v = 120 ÷ 1,5 = 80 km/h."}, {"materia": "fis", "texto_base": null, "enunciado": "Um carro de 1.000 kg acelera a 2 m/s². A força resultante sobre ele é de", "opcoes": ["1.000 N.", "20.000 N.", "2.000 N.", "500 N.", "1.002 N."], "gabarito": 2, "explicacao": "Segunda lei de Newton: F = m × a = 1.000 × 2 = 2.000 N."}, {"materia": "fis", "texto_base": null, "enunciado": "Um objeto de 2 kg se move a 3 m/s. Sua energia cinética é de", "opcoes": ["12 J.", "6 J.", "3 J.", "18 J.", "9 J."], "gabarito": 4, "explicacao": "Ec = m × v² ÷ 2 = 2 × 9 ÷ 2 = 9 J."}, {"materia": "fis", "texto_base": "Uma família consome energia elétrica com um chuveiro de 5.500 W, ligado em média 20 minutos por dia, durante 30 dias.", "enunciado": "O consumo mensal de energia desse chuveiro é de", "opcoes": ["165 kWh.", "5,5 kWh.", "55 kWh.", "3.300 kWh.", "110 kWh."], "gabarito": 2, "explicacao": "5.500 W = 5,5 kW. Tempo no mês: 20 min × 30 = 600 min = 10 h. Energia = 5,5 kW × 10 h = 55 kWh."}, {"materia": "fis", "texto_base": null, "enunciado": "Um aparelho ligado em 220 V tem resistência de 44 Ω. A corrente elétrica que passa por ele é de", "opcoes": ["5 A.", "0,2 A.", "264 A.", "176 A.", "9.680 A."], "gabarito": 0, "explicacao": "Lei de Ohm: I = U ÷ R = 220 ÷ 44 = 5 A."}, {"materia": "fis", "texto_base": null, "enunciado": "No espaço, astronautas não conseguem se comunicar gritando, sem rádio, porque", "opcoes": ["o som só se propaga na água.", "o som viaja rápido demais no vácuo.", "o som é uma onda mecânica e precisa de um meio material para se propagar.", "a luz bloqueia o som.", "o frio congela as ondas sonoras."], "gabarito": 2, "explicacao": "O som precisa de um meio (ar, água, sólido). As ondas de rádio são eletromagnéticas e se propagam no vácuo."}, {"materia": "mat", "texto_base": null, "enunciado": "Uma camiseta custa R$ 80,00 e está com 15% de desconto. O preço com desconto é", "opcoes": ["R$ 92,00.", "R$ 65,00.", "R$ 12,00.", "R$ 68,00.", "R$ 70,00."], "gabarito": 3, "explicacao": "15% de 80 = 12. 80 − 12 = 68."}, {"materia": "mat", "texto_base": null, "enunciado": "Uma pessoa aplicou R$ 2.000,00 a juros simples de 3% ao mês durante 5 meses. O montante ao final foi de", "opcoes": ["R$ 2.300,00.", "R$ 2.150,00.", "R$ 2.060,00.", "R$ 2.318,55.", "R$ 3.000,00."], "gabarito": 0, "explicacao": "J = 2.000 × 0,03 × 5 = 300. M = 2.000 + 300 = 2.300. O valor 2.318,55 seria o montante com juros compostos."}, {"materia": "mat", "texto_base": null, "enunciado": "Seis pedreiros constroem um muro em 10 dias. Mantido o mesmo ritmo, quatro pedreiros construiriam o mesmo muro em", "opcoes": ["6,7 dias.", "15 dias.", "12 dias.", "8 dias.", "20 dias."], "gabarito": 1, "explicacao": "As grandezas são inversamente proporcionais: 6 × 10 = 4 × d, então d = 60 ÷ 4 = 15 dias."}, {"materia": "mat", "texto_base": null, "enunciado": "Um estudante tirou 6, 7 e 8 nas três primeiras provas. Para ter média aritmética 7,5 nas quatro provas, ele precisa tirar na quarta prova", "opcoes": ["8.", "8,5.", "7,5.", "9.", "10."], "gabarito": 3, "explicacao": "Soma necessária: 7,5 × 4 = 30. Já tem 21. 30 − 21 = 9."}, {"materia": "mat", "texto_base": null, "enunciado": "Um terreno retangular mede 12 m por 25 m. Sua área é de", "opcoes": ["74 m².", "600 m².", "37 m².", "300 m².", "150 m²."], "gabarito": 3, "explicacao": "Área = 12 × 25 = 300 m². O valor 74 m seria o perímetro."}, {"materia": "mat", "texto_base": null, "enunciado": "Uma caixa-d'água tem formato de cubo com aresta interna de 2 m. Sua capacidade é de", "opcoes": ["8.000 litros.", "6.000 litros.", "800 litros.", "4.000 litros.", "80.000 litros."], "gabarito": 0, "explicacao": "V = 2³ = 8 m³. Como 1 m³ = 1.000 L, a capacidade é de 8.000 L."}, {"materia": "mat", "texto_base": null, "enunciado": "Lançando-se dois dados comuns, a probabilidade de a soma dos resultados ser 7 é", "opcoes": ["1/12.", "7/36.", "7/12.", "1/36.", "1/6."], "gabarito": 4, "explicacao": "Há 36 resultados possíveis e 6 favoráveis: (1,6), (2,5), (3,4), (4,3), (5,2) e (6,1). 6/36 = 1/6."}, {"materia": "mat", "texto_base": null, "enunciado": "Na planta de uma casa, feita na escala 1:50, uma parede mede 8 cm. O comprimento real da parede é de", "opcoes": ["0,4 m.", "4 m.", "40 m.", "8 m.", "50 m."], "gabarito": 1, "explicacao": "8 cm × 50 = 400 cm = 4 m."}, {"materia": "mat", "texto_base": null, "enunciado": "Uma corrida de táxi custa R$ 5,00 de bandeirada mais R$ 2,50 por quilômetro rodado. Uma corrida de 10 km custa", "opcoes": ["R$ 30,00.", "R$ 25,00.", "R$ 75,00.", "R$ 27,50.", "R$ 35,00."], "gabarito": 0, "explicacao": "P(x) = 5 + 2,5x. P(10) = 5 + 25 = 30."}, {"materia": "mat", "texto_base": null, "enunciado": "Um produto teve dois aumentos sucessivos de 10%. O aumento total acumulado foi de", "opcoes": ["20%.", "22%.", "21%.", "11%.", "1%."], "gabarito": 2, "explicacao": "1,1 × 1,1 = 1,21, ou seja, aumento de 21%. Os aumentos percentuais sucessivos não se somam."}, {"materia": "mat", "texto_base": null, "enunciado": "Uma escada de 5 m está apoiada em uma parede, com o pé a 3 m da base da parede. A altura em que a escada toca a parede é de", "opcoes": ["2 m.", "8 m.", "3,5 m.", "√34 m.", "4 m."], "gabarito": 4, "explicacao": "Teorema de Pitágoras: 5² = 3² + h², então h² = 25 − 9 = 16 e h = 4 m."}, {"materia": "mat", "texto_base": null, "enunciado": "A mediana dos valores 2, 5, 3, 9 e 7 é", "opcoes": ["5,2.", "3.", "9.", "5.", "7."], "gabarito": 3, "explicacao": "Ordenando: 2, 3, 5, 7, 9. O valor central é 5. O valor 5,2 é a média aritmética (26 ÷ 5)."}, {"materia": "mat", "texto_base": null, "enunciado": "Uma receita usa 3 ovos para render 8 porções. Para fazer 24 porções, mantendo a proporção, são necessários", "opcoes": ["8 ovos.", "12 ovos.", "24 ovos.", "6 ovos.", "9 ovos."], "gabarito": 4, "explicacao": "24 porções é o triplo de 8, então são necessários 3 × 3 = 9 ovos."}, {"materia": "mat", "texto_base": null, "enunciado": "O lucro de uma pequena empresa, em milhares de reais, é dado por L(x) = −x² + 10x, em que x é a quantidade produzida, em centenas. O lucro máximo é de", "opcoes": ["100 mil reais.", "5 mil reais.", "50 mil reais.", "25 mil reais.", "10 mil reais."], "gabarito": 3, "explicacao": "O vértice ocorre em x = −b ÷ 2a = −10 ÷ (−2) = 5. L(5) = −25 + 50 = 25, ou seja, 25 mil reais."}, {"materia": "mat", "texto_base": null, "enunciado": "Na sequência 5, 8, 11, 14, …, o 20º termo é", "opcoes": ["60.", "62.", "68.", "59.", "65."], "gabarito": 1, "explicacao": "PA de razão 3: a₂₀ = 5 + 19 × 3 = 5 + 57 = 62."}, {"materia": "mat", "texto_base": null, "enunciado": "R$ 1.000,00 foram aplicados a juros compostos de 10% ao ano. Após 2 anos, o montante será de", "opcoes": ["R$ 1.020,00.", "R$ 1.210,00.", "R$ 1.200,00.", "R$ 1.100,00.", "R$ 1.331,00."], "gabarito": 1, "explicacao": "M = 1.000 × 1,1² = 1.000 × 1,21 = 1.210. O valor 1.200 seria com juros simples, e 1.331 após 3 anos."}, {"materia": "mat", "texto_base": null, "enunciado": "Quantas senhas de 3 algarismos distintos podem ser formadas com os algarismos de 0 a 9?", "opcoes": ["120.", "30.", "720.", "504.", "1.000."], "gabarito": 2, "explicacao": "Princípio multiplicativo: 10 × 9 × 8 = 720. Se os algarismos pudessem se repetir, seriam 1.000."}, {"materia": "mat", "texto_base": null, "enunciado": "A roda de uma bicicleta tem raio de 30 cm. Usando π = 3,14, a cada volta completa a bicicleta avança aproximadamente", "opcoes": ["188,4 cm.", "94,2 cm.", "282,6 cm.", "60 cm.", "2.826 cm."], "gabarito": 0, "explicacao": "Comprimento da circunferência: C = 2πr = 2 × 3,14 × 30 = 188,4 cm. O valor 2.826 seria a área em cm²."}, {"materia": "mat", "texto_base": null, "enunciado": "Um carro faz 12 km por litro de gasolina. Em uma viagem de 300 km, com a gasolina a R$ 6,00 o litro, o gasto com combustível será de", "opcoes": ["R$ 25,00.", "R$ 72,00.", "R$ 180,00.", "R$ 120,00.", "R$ 150,00."], "gabarito": 4, "explicacao": "Litros: 300 ÷ 12 = 25 L. Gasto: 25 × 6 = R$ 150,00."}, {"materia": "mat", "texto_base": null, "enunciado": "Em uma escola, 40% dos 250 estudantes do 3º ano vão de ônibus para a aula. O número de estudantes do 3º ano que usam ônibus é", "opcoes": ["150.", "160.", "40.", "100.", "62."], "gabarito": 3, "explicacao": "40% de 250 = 0,4 × 250 = 100. Os 150 restantes não usam ônibus."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('enem', date '2026-10-25', 'Simulado 1 · Enem', 'Enem', 300, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data, s.titulo, s.estilo, s.duracao_min, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.trilha = 'enem' and s.data = date '2026-10-25' group by s.id;
